// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 value, bytes calldata data) public {
        vm.assume(caller != address(0));
        address originalOwner = c.owner();
        vm.prank(caller);
        vm.deal(caller, value);
        bool ok;
        try c.sendMoney(address(0), value, data) { ok = true; } catch { ok = false; }
        if (caller != originalOwner) {
            assertTrue(!ok);
        }
    }
}
